function uid() {
  return Math.random().toString(36).slice(2, 6) + Date.now().toString(36).slice(-4);
}

async function getIndex() {
  try {
    const r = await window.storage.get("weddings-index", true);
    return r ? JSON.parse(r.value) : [];
  } catch { return []; }
}
async function saveIndex(list) {
  try { await window.storage.set("weddings-index", JSON.stringify(list), true); } catch {}
}
async function saveWedding(id, data) {
  try { await window.storage.set(`wedding:${id}`, JSON.stringify(data), true); } catch {}
}

