/* Soundwave signature — pulses gently, echoes the "waveform" of a live set
   and doubles as a scroll cue under the hero. */
function Waveform({ bars = 28, className = "" }) {
  const heights = useRef(Array.from({ length: bars }, () => 20 + Math.random() * 80));
  return (
    <div className={`flex items-end justify-center gap-[3px] ${className}`} style={{ height: 44 }}>
      {heights.current.map((h, i) => (
        <div
          key={i}
          className="w-[3px] rounded-full bg-gradient-to-t from-[#C9A227] to-[#E8C766] animate-pulse"
          style={{ height: `${h}%`, animationDelay: `${i * 60}ms`, animationDuration: "1.6s" }}
        />
      ))}
    </div>
  );
}

